syntax:
let name = value;
let mut name = value;
let name: Type = value;

example:
let age = 25;        // ثابت، لا يمكن تعديله
let mut score = 0;   // قابل للتعديل
score += 10;

// shadowing: متغيّر جديد بنفس الاسم
let x = "5";
let x: i32 = x.parse().unwrap(); // الآن x عدد صحيح

syntax:
struct Name { field: Type, ... }
struct TupleName(Type, Type);
let instance = Name { field: value };

example:
struct User {
    name: String,
    age: u32,
}

let u = User { name: String::from("سارة"), age: 30 };
println!("{} عمرها {}", u.name, u.age);

// هيكل صف
struct Point(f64, f64);
let p = Point(1.0, 2.0);
println!("{}", p.0);

syntax:
enum Name {
    Variant1,
    Variant2(Type),
    Variant3 { field: Type },
}

example:
enum Shape {
    Circle(f64),
    Rectangle(f64, f64),
    Point,
}

let s = Shape::Circle(2.0);

let area = match s {
    Shape::Circle(r) => 3.14 * r * r,
    Shape::Rectangle(w, h) => w * h,
    Shape::Point => 0.0,
};

syntax:
impl TypeName {
    fn method(&self) -> T { ... }
    fn new() -> Self { ... }
}
impl TraitName for TypeName { ... }

example:
struct Circle { radius: f64 }

impl Circle {
    fn new(radius: f64) -> Self {
        Circle { radius }
    }

    fn area(&self) -> f64 {
        3.14 * self.radius * self.radius
    }
}

let c = Circle::new(2.0);
println!("{}", c.area());

syntax:
trait Name {
    fn method(&self) -> T;
    fn default_method(&self) -> T { ... }
}

example:
trait Summary {
    fn summarize(&self) -> String;

    fn preview(&self) -> String {
        format!("معاينة: {}", self.summarize())
    }
}

struct Article { title: String }

impl Summary for Article {
    fn summarize(&self) -> String {
        self.title.clone()
    }
}

syntax:
match value {
    pattern1 => expr,
    pattern2 if condition => expr,
    _ => expr,
}

example:
let n = 7;

match n {
    0 => println!("صفر"),
    x if x % 2 == 0 => println!("{x} زوجي"),
    1..=9 => println!("رقم صغير"),
    _ => println!("غير ذلك"),
}

#[derive(Debug, Clone, PartialEq)]
struct Point { x: i32, y: i32 }

let a = Point { x: 1, y: 2 };
let b = a.clone();

println!("{:?}", a);   // طباعة تصحيحية بفضل Debug
println!("{}", a == b); // مقارنة بفضل PartialEq

fn divide(a: f64, b: f64) -> Result<f64, String> {
    if b == 0.0 {
        Err(String::from("القسمة على صفر"))
    } else {
        Ok(a / b)
    }
}

match divide(10.0, 2.0) {
    Ok(v) => println!("الناتج {v}"),
    Err(e) => println!("خطأ: {e}"),
}

let x: Option<i32> = Some(5);
println!("{}", x.unwrap_or(0));

syntax:
let v: Vec<T> = Vec::new();
let v = vec![v1, v2, v3];
v.push(value);

example:
let mut nums: Vec<i32> = Vec::new();
nums.push(1);
nums.push(2);

let doubled: Vec<i32> = vec![1, 2, 3]
    .iter()
    .map(|x| x * 2)
    .collect();

println!("{:?}", doubled); // [2, 4, 6]

syntax:
let s: String = String::from("text");
let s: &str = "text";
s.push_str("...");

example:
let mut owned = String::from("مرحبًا");
owned.push_str(" بالعالم");

fn greet(name: &str) -> String {
    format!("أهلًا {name}")
}

println!("{}", greet(&owned));

syntax:
use std::collections::HashMap;
let mut map: HashMap<K, V> = HashMap::new();
map.insert(key, value);

example:
use std::collections::HashMap;

let mut scores = HashMap::new();
scores.insert("سارة", 90);
scores.insert("علي", 85);

match scores.get("سارة") {
    Some(score) => println!("النتيجة: {score}"),
    None => println!("غير موجود"),
}

*scores.entry("علي").or_insert(0) += 5;
